    <div class="user-profile-card">
    <div class="user-header">
            <img src="${cover}" class="user-avatar">
            <div class="user-meta">
                <h2 class="username">${name}</h2>
                <p class="user-bio">${info}</p>
            </div>
        </div>

        <div class="copy-section">
            <div class="copy-content" id="copyContent">
${type}${name}::${yurl}
            </div>
            <button class="copy-btn" onclick="handleCopy()">
                <span class="copy-icon">⎘</span>
                <span class="copy-text">一键复制后粘贴到分类URL</span>
            </button>
            <button class="copy-btn" onclick="toAdd()">
                <span class="copy-icon">📚</span>
                <span class="copy-text">加入书架</span>
            </button>
            ${this.isL()?c:""}
            <div class="copy-feedback" id="copyFeedback"></div>
        </div>


    </div>

    <style>
        .user-profile-card{
            max-width: 600px;
            margin: 0 auto;
            padding: 25px;
            background: white;
            border-radius: 12px;
            box-shadow: 0 5px 15px rgba(0,0,0,0.08);
            font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
        }

        .user-header {
            display: flex;
            align-items: flex-start;
            margin-bottom: 20px;
        padding: 15px;
        background: linear-gradient(135deg, #f5f7fa 0%, #c3cfe2 100%);
